# ─── HELPERS ──────────────────────────────────────────────────────────────────
def normalise_id(mid: str) -> str:
    return mid.strip().lower().lstrip("<").rstrip(">")


def make_logo_image(height=44, bg_color=(26, 29, 39)):
    """Return a PhotoImage scaled to the given height, preserving aspect ratio.
    Composites transparent PNG over bg_color so tkinter renders it correctly."""
    try:
        data = base64.b64decode(LOGO_B64)
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        ratio = img.width / img.height
        w = max(1, int(height * ratio))
        img = img.resize((w, height), Image.LANCZOS)
        # Flatten RGBA onto a solid background so tkinter Label renders it correctly
        bg = Image.new("RGBA", img.size, bg_color + (255,))
        bg.paste(img, mask=img.split()[3])
        return ImageTk.PhotoImage(bg.convert("RGB"))
    except Exception:
        return None

def make_logo_pil(size=(32, 32)):
    """Return a PIL Image for favicon/ICO use (square, fully transparent bg)."""
    try:
        data = base64.b64decode(LOGO_B64)
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        # Fit into square canvas preserving aspect ratio
        img.thumbnail(size, Image.LANCZOS)
        # Fully transparent canvas — ICO format supports alpha
        canvas = Image.new("RGBA", size, (0, 0, 0, 0))
        x = (size[0] - img.width) // 2
        y = (size[1] - img.height) // 2
        canvas.paste(img, (x, y), img.split()[3])
        return canvas
    except Exception:
        return None


# ─── STYLED WIDGETS ───────────────────────────────────────────────────────────
def flat_btn(parent, text, cmd, accent=False, small=False):
    bg = C["accent"] if accent else C["btn_bg"]
    fg = C["btn_fg"]
    pad = (10, 5) if small else (16, 8)
    b = tk.Button(parent, text=text, command=cmd, bg=bg, fg=fg,
                  font=FONTS["small"] if small else FONTS["body"],
                  relief="flat", cursor="hand2", padx=pad[0], pady=pad[1],
                  activebackground=C["accent_dk"] if accent else C["btn_hov"],
                  activeforeground=fg, bd=0)
    return b


def label(parent, text, style="body", **kw):
    return tk.Label(parent, text=text, font=FONTS[style],
                    bg=kw.pop("bg", C["bg"]), fg=kw.pop("fg", C["text"]), **kw)


def card(parent, **kw):
    f = tk.Frame(parent, bg=C["bg"], bd=1, relief="solid",
                 highlightbackground=C["border"], highlightthickness=1, **kw)
    return f


def stat_pill(parent, value, label_text, color=None):
    f = tk.Frame(parent, bg="#FFFFFF", bd=1, relief="flat",
                 highlightbackground=C["border"], highlightthickness=1)
    tk.Label(f, text=str(value), font=("Segoe UI", 20, "bold"),
             bg="#FFFFFF", fg=color or C["accent"]).pack(padx=16, pady=(10, 0))
    tk.Label(f, text=label_text, font=FONTS["small"],
             bg="#FFFFFF", fg=C["muted"]).pack(padx=16, pady=(0, 10))
    return f


