    def _build_sidebar(self, parent):
        sb = tk.Frame(parent, bg=C["sidebar"], width=220,
                      bd=0, highlightbackground=C["sidebar_b"], highlightthickness=1)
        sb.pack(side="left", fill="y")
        sb.pack_propagate(False)

