    def _browse_ual(self):
        path = filedialog.askopenfilename(
            title="Select UAL Export",
            filetypes=[("Excel/CSV files", "*.xlsx *.xls *.csv"), ("All files", "*.*")]
        )
        if not path:
            return
        fname = Path(path).name
        self._show_loading(fname)
        self._set_status(f"Loading {fname}...")
        threading.Thread(target=self._load_ual, args=(path,), daemon=True).start()

    def _read_xlsx(self, path):
        """Read an XLSX file reliably. Uses openpyxl directly to avoid
        the read_only iterator deadlock that affects pd.read_excel."""
        import openpyxl
        wb = openpyxl.load_workbook(path, read_only=False, data_only=True)
        ws = wb.active
        rows = list(ws.iter_rows(values_only=True))
        wb.close()
        if not rows:
            return pd.DataFrame()
        headers = [str(c) if c is not None else f"Col{i}" for i, c in enumerate(rows[0])]
        data = []
        for row in rows[1:]:
            data.append([str(c) if c is not None else "" for c in row])
        return pd.DataFrame(data, columns=headers)

    def _load_ual(self, path):
        try:
            self.after(0, lambda: self._ual_file_lbl.configure(
                text="Loading… please wait", fg=C["muted"]))
            if path.lower().endswith(".csv"):
                df = pd.read_csv(path, dtype=str, low_memory=False,
                                 encoding_errors="replace")
            else:
                df = self._read_xlsx(path)
            df = df.fillna("").astype(str)
            self.ual_df = df
            self.after(0, self._ual_loaded, path, df)
        except Exception as e:
            err = str(e)
            self.after(0, lambda: (
                self._hide_loading(),
                self._ual_file_lbl.configure(text="Load failed", fg=C["red"]),
                messagebox.showerror("Load Error",
                    f"Could not load file:\n{err}\n\n"
                    "Try saving as CSV from Excel (File → Save As → CSV UTF-8).")
            ))

    def _inspect_ual(self, df):
        """Analyse the loaded UAL CSV and surface issues before extraction runs."""
        cols_lower = {c.lower().strip(): c for c in df.columns}

        def find_col(*candidates):
            for c in candidates:
                if c.lower() in cols_lower:
                    return cols_lower[c.lower()]
            for c in candidates:
                for k, v in cols_lower.items():
                    if c.lower() in k:
                        return v
            return None

        audit_col = find_col("AuditData", "Audit Data", "auditdata", "audit_data")
        op_col    = find_col("Operations", "Operation", "operations", "operation")

        issues = []
        info   = []

        # Check columns exist
        if not audit_col:
            issues.append(f"Cannot find AuditData column. Columns present: {', '.join(df.columns.tolist())}")
        else:
            info.append(f"AuditData column  : \'{audit_col}\'")
            # Update the mapping field to match
            self.ual_col_audit.set(audit_col)

        if not op_col:
            issues.append(f"Cannot find Operations/Operation column.")
        else:
            info.append(f"Operation column  : \'{op_col}\'")
            self.ual_col_op.set(op_col)

        if not audit_col or not op_col:
            return issues, info, {}

        # Count operation types
        op_counts = df[op_col].str.strip().value_counts()
        mia_col_name = next((k for k in op_counts.index if "mailitemsaccessed" in str(k).lower()), None)
        mia_count = int(op_counts.get(mia_col_name, 0)) if mia_col_name else 0
        info.append(f"MailItemsAccessed : {mia_count:,} rows (out of {len(df):,} total)")
        if mia_count == 0:
            issues.append("No MailItemsAccessed rows found. Check the UAL contains this operation, or the Operation column is correct.")

        # Sample AuditData from a MIA row
        rest_count = 0
        sync_count = 0
        json_err   = 0
        sample_keys = set()
        if mia_col_name and mia_count > 0:
            mia_rows = df[df[op_col].str.strip() == mia_col_name]
            for _, row in mia_rows.head(50).iterrows():
                raw = str(row.get(audit_col, "")).strip()
                if raw.startswith('"') and raw.endswith('"'):
                    raw = raw[1:-1].replace('\"\"'  , '\"'  )
                try:
                    j = json.loads(raw)
                    sample_keys.update(j.keys())
                    if j.get("Folders"):
                        sync_count += 1
                    else:
                        rest_count += 1
                except Exception:
                    json_err += 1

            info.append(f"Access type sample: {sync_count} sync (have IDs) / {rest_count} REST-only (no IDs) in first 50")
            if json_err:
                issues.append(f"{json_err} AuditData cells failed JSON parsing in first 50 MIA rows.")
            if sync_count == 0 and rest_count > 0:
                issues.append(
                    "All sampled events are REST/Graph-protocol accesses — these never contain InternetMessageId. "
                    "The TA may have used OWA, mobile app, or Graph API. "
                    "Sync-protocol (MAPI/EWS) access events are needed to get message IDs."
                )
            if sample_keys:
                info.append(f"AuditData keys    : {', '.join(sorted(sample_keys)[:12])}")

        return issues, info, {"mia_count": mia_count, "sync": sync_count, "rest": rest_count}


    def _ual_loaded(self, path, df):
        self._hide_loading()
        fname = Path(path).name
        self._ual_file_lbl.configure(
            text="✓  " + fname + "  —  " + f"{len(df):,} rows, {len(df.columns)} columns",
            fg=C["green"])
        col_preview = ", ".join(df.columns[:8].tolist())
        if len(df.columns) > 8:
            col_preview += "…"
        self._ual_info.configure(text="Columns: " + col_preview)
        self._btn_to_parse.configure(state="normal")
        self._mark_done("ual")
        self._set_status(f"UAL loaded: {len(df):,} rows")
        self._build_preview(self._ual_preview_frame, df, title="UAL Preview (first 5 rows)")

        # Run inspector and show results
        issues, info_lines, stats = self._inspect_ual(df)
        frame = self._ual_inspect_frame
        for w in frame.winfo_children():
            w.destroy()
        bg   = "#ECEFFE" if issues else "#E8FBF4"
        bord = "#E95555" if issues else "#2EAD7A"
        frame.configure(bg=bg, highlightbackground=bord, highlightthickness=1)
        hdr = "⚠  Issues found — check before extracting:" if issues else "✓  File looks good"
        tk.Label(frame, text=hdr, font=FONTS["h3"], bg=bg,
                 fg=C["red"] if issues else C["green"]).pack(anchor="w", padx=14, pady=(10, 4))
        warn_lines = ["  ⚠ " + x for x in issues]
        ok_lines   = ["  ✓ " + x for x in info_lines]
        all_text   = "\n".join(warn_lines + ok_lines)
        tk.Label(frame, text=all_text, font=FONTS["mono"], bg=bg,
                 fg="#1A1D27" if issues else "#1A3A2A",
                 justify="left").pack(anchor="w", padx=14, pady=(0, 10))

    def _build_preview(self, frame, df, title="Preview"):
        for w in frame.winfo_children():
            w.destroy()
        tk.Label(frame, text=title, font=FONTS["h3"],
                 bg=C["bg"], fg=C["text"]).pack(anchor="w", pady=(0, 8))
        self._build_table(frame, df.head(5), max_cols=6)

    def _build_table(self, parent, df, max_cols=None, highlight_col=None, matched_col=None):
        cols = list(df.columns)[:max_cols] if max_cols else list(df.columns)
        container = tk.Frame(parent, bg=C["border"], bd=0)
        container.pack(fill="x")
        vsb = ttk.Scrollbar(container, orient="vertical")
        hsb = ttk.Scrollbar(container, orient="horizontal")
        tv = ttk.Treeview(container, columns=cols, show="headings",
                          yscrollcommand=vsb.set, xscrollcommand=hsb.set,
                          height=min(len(df), 15))
        vsb.configure(command=tv.yview)
        hsb.configure(command=tv.xview)
        vsb.pack(side="right", fill="y")
        hsb.pack(side="bottom", fill="x")
        tv.pack(fill="both", expand=True)

        style = ttk.Style()
        style.configure("Treeview", font=FONTS["small"], rowheight=22, background=C["bg"])
        style.configure("Treeview.Heading", font=FONTS["tag"], background=C["navy"],
                        foreground="#FFFFFF")
        style.map("Treeview", background=[("selected", C["accent_sel"])])

        for col in cols:
            tv.heading(col, text=col)
            tv.column(col, width=150, anchor="w", stretch=True)

        tv.tag_configure("match", background=C["row_match"])
        tv.tag_configure("alt", background=C["row_alt"])

        for i, row in df.iterrows():
            vals = [str(row[c])[:80] for c in cols]
            tag = ()
            if matched_col and str(row.get(matched_col, "")) == "YES":
                tag = ("match",)
            elif i % 2 == 1:
                tag = ("alt",)
            tv.insert("", "end", values=vals, tags=tag)

        return tv

