    def _clear_placeholder(self, event, entry, placeholder):
        if entry.get() == placeholder:
            entry.delete(0, "end")
            entry.configure(fg=C["text"])

    def _set_placeholder(self, event, entry, placeholder, var):
        if not entry.get():
            entry.insert(0, placeholder)
            entry.configure(fg=C["muted"])

    def _clear_filters(self):
        self._filter_session.set("")
        self._filter_user.set("")

    def _run_extraction(self):
        if self.ual_df is None:
            messagebox.showwarning("No UAL", "Please load a UAL file first.")
            return
        self._parse_progress.pack(fill="x", pady=(4, 0))
        self._parse_progress["value"] = 0
        self._parse_status_lbl.configure(text="Starting extraction...")
        threading.Thread(target=self._extract_ids, daemon=True).start()

    def _extract_ids(self):
        df = self.ual_df
        total = len(df)
        cols_lower = {c.lower().strip(): c for c in df.columns}

        # Robust column detection
        def find_col(*candidates):
            for c in candidates:
                if c.lower() in cols_lower:
                    return cols_lower[c.lower()]
            for c in candidates:
                for k, v in cols_lower.items():
                    if c.lower() in k:
                        return v
            return None

        audit_col_pref = self.ual_col_audit.get().strip()
        op_col_pref    = self.ual_col_op.get().strip()

        audit_col = find_col(audit_col_pref, "AuditData", "Audit Data", "auditdata", "audit_data")
        op_col    = find_col(op_col_pref, "Operations", "Operation", "operations", "operation")
        user_col  = find_col("UserId", "UserID", "userid", "User")
        date_col  = find_col("CreationDate", "Date", "creationdate")

        # Filter values — ignore placeholder text
        raw_sess = self._filter_session.get().strip()
        raw_user = self._filter_user.get().strip()
        SESS_PH = "e.g. 3.XXX!..."
        USER_PH = "e.g. user@contoso.com"
        session_f = "" if (not raw_sess or raw_sess == SESS_PH) else raw_sess.lower()
        user_f    = "" if (not raw_user or raw_user == USER_PH) else raw_user.lower()

        diag = {
            "total_rows": total,
            "audit_col": audit_col or "NOT FOUND",
            "op_col": op_col or "NOT FOUND",
            "session_filter": session_f or "(none)",
            "user_filter": user_f or "(none)",
            "mia_rows": 0,
            "user_filtered": 0,
            "rest_only": 0,
            "json_errors": 0,
            "ids_found": 0,
        }

        if not audit_col:
            self.after(0, lambda: messagebox.showerror(
                "Column Not Found",
                f"Cannot find AuditData column.\n\n"
                f"Columns in your file:\n" + "\n".join(df.columns.tolist()[:20]) +
                "\n\nUpdate the 'AuditData column' field on Step 1 to match exactly."
            ))
            self.after(0, lambda: self._parse_progress.pack_forget())
            return

        if not op_col:
            self.after(0, lambda: messagebox.showerror(
                "Column Not Found",
                f"Cannot find Operations column.\n\n"
                f"Columns in your file:\n" + "\n".join(df.columns.tolist()[:20]) +
                "\n\nUpdate the 'Operation column' field on Step 1 to match exactly."
            ))
            self.after(0, lambda: self._parse_progress.pack_forget())
            return

        ids = set()
        rows_out = []

        for i, row in df.iterrows():
            op = str(row.get(op_col, "")).strip().lower()
            if "mailitemsaccessed" not in op:
                continue
            diag["mia_rows"] += 1

            uid = str(row.get(user_col, "")) if user_col else ""
            if user_f and user_f not in uid.lower():
                diag["user_filtered"] += 1
                continue

            raw = str(row.get(audit_col, "")).strip()
            if raw.startswith('"') and raw.endswith('"'):
                raw = raw[1:-1].replace('""''"', '"''"')
            if not raw or raw == "nan":
                continue

            try:
                j = json.loads(raw)
            except Exception:
                try:
                    j = json.loads(json.loads(f'"{raw}"'))
                except Exception:
                    diag["json_errors"] += 1
                    continue

            sess = str(j.get("SessionId", ""))
            if not sess:
                ctx = j.get("AppAccessContext", {})
                if isinstance(ctx, dict):
                    sess = str(ctx.get("AADSessionId", ""))
            if session_f and session_f not in sess.lower():
                continue

            folders = j.get("Folders", [])
            if not folders:
                diag["rest_only"] += 1
                continue

            event_ids = []
            for folder in folders:
                if not isinstance(folder, dict):
                    continue
                for item in folder.get("FolderItems", []):
                    if not isinstance(item, dict):
                        continue
                    mid = item.get("InternetMessageId") or item.get("internetMessageId")
                    if mid and str(mid).strip():
                        ids.add(str(mid).strip())
                        event_ids.append(str(mid).strip())

            if event_ids:
                diag["ids_found"] += len(event_ids)
                rows_out.append({
                    "Date":          str(row.get(date_col, "")) if date_col else "",
                    "UserId":        uid,
                    "Session":       sess[:60] if sess else "",
                    "ClientIP":      str(j.get("ClientIPAddress", j.get("ClientIP", ""))),
                    "IDs Extracted": len(event_ids),
                })

            if i % 200 == 0:
                pct = int((i / total) * 100)
                self.after(0, lambda v=pct, ii=i: (
                    self._parse_progress.configure(value=v),
                    self._parse_status_lbl.configure(
                        text=f"Processing row {ii:,} of {total:,}\u2026")
                ))

        self.extracted_ids = ids
        self.after(0, lambda: self._parse_done(ids, rows_out, diag))

    def _parse_done(self, ids, rows, diag):
        self._parse_progress.pack_forget()
        self._parse_status_lbl.configure(text="")

        errors = diag.get("json_errors", 0)
        rest   = diag.get("rest_only", 0)
        mia    = diag.get("mia_rows", 0)

        # Stats pills
        for w in self._parse_stats_frame.winfo_children():
            w.destroy()
        pills = tk.Frame(self._parse_stats_frame, bg=C["bg"])
        pills.pack(fill="x", pady=(0, 12))
        for val, lbl_txt, col in [
            (len(ids),  "Unique Message IDs",  C["accent"]),
            (len(rows), "Events with IDs",     C["green"]),
            (mia,       "MailItemsAccessed",   C["navy"]),
            (rest,      "REST-only (no IDs)",  C["amber"]),
            (errors,    "JSON Parse Errors",   C["red"] if errors else C["muted"]),
        ]:
            sp = stat_pill(pills, f"{val:,}", lbl_txt, color=col)
            sp.pack(side="left", padx=(0, 8))

        # Diagnostics card — always visible
        for w in self._parse_result_frame.winfo_children():
            w.destroy()

        diag_card = tk.Frame(self._parse_result_frame, bg="#ECEFFE", bd=1, relief="flat",
                             highlightbackground="#6374F8", highlightthickness=1)
        diag_card.pack(fill="x", pady=(0, 14))
        tk.Label(diag_card, text="EXTRACTION DIAGNOSTICS", font=FONTS["tag"],
                 bg="#ECEFFE", fg="#1A1D27").pack(anchor="w", padx=14, pady=(10, 4))
        diag_lines = [
            f"  Audit column used    : {diag.get('audit_col')}",
            f"  Operation column     : {diag.get('op_col')}",
            f"  Session filter       : {diag.get('session_filter')}",
            f"  User filter          : {diag.get('user_filter')}",
            f"  Total rows scanned   : {diag.get('total_rows', 0):,}",
            f"  MailItemsAccessed    : {mia:,}",
            f"  User-filtered out    : {diag.get('user_filtered', 0):,}",
            f"  REST events (no IDs) : {rest:,}  ← these never have InternetMessageId",
            f"  JSON parse errors    : {errors:,}",
            f"  Unique IDs extracted : {len(ids):,}",
        ]
        tk.Label(diag_card, text="\n".join(diag_lines), font=FONTS["mono"],
                 bg="#ECEFFE", fg="#1A1D27", justify="left").pack(anchor="w", padx=14, pady=(0, 10))

        if len(ids) == 0 and mia > 0:
            hint = (
                "0 IDs extracted but MailItemsAccessed events were found.\n\n"
                f"  REST-only events: {rest:,} — these are graph/REST accesses with no FolderItems.\n"
                "  Only sync-protocol events (MAPI/EWS) carry InternetMessageId.\n\n"
                "  If your session filter is active, try clearing it.\n"
                "  If all events are REST-only, the TA used a client that doesn't log FolderItems."
            )
            tk.Label(self._parse_result_frame, text=hint, font=FONTS["small"],
                     bg="#ECEFFE", fg=C["red"], justify="left", wraplength=800,
                     relief="flat", bd=0, padx=12, pady=10).pack(fill="x", pady=(0, 10))
        elif len(ids) == 0 and mia == 0:
            hint = (
                "No MailItemsAccessed rows found.\n\n"
                f"  Operation column detected: '{diag.get('op_col')}'\n"
                "  Check that your UAL contains MailItemsAccessed operations,\n"
                "  and that the Operation column name above is correct."
            )
            tk.Label(self._parse_result_frame, text=hint, font=FONTS["small"],
                     bg="#ECEFFE", fg=C["red"], justify="left", wraplength=800,
                     relief="flat", bd=0, padx=12, pady=10).pack(fill="x", pady=(0, 10))

        if rows:
            tk.Label(self._parse_result_frame, text="Events with Extracted IDs",
                     font=FONTS["h3"], bg=C["bg"], fg=C["text"]).pack(anchor="w", pady=(4, 6))
            rdf = pd.DataFrame(rows)
            self._build_table(self._parse_result_frame, rdf, max_cols=5)

        self._btn_dl_ids.configure(state="normal" if ids else "disabled")
        self._btn_to_cs.configure(state="normal")
        self._mark_done("parse")
        self._set_status(f"Extracted {len(ids):,} unique IDs from {len(rows):,} events  |  {rest:,} REST-only events skipped")

    def _download_ids(self):
        if not self.extracted_ids:
            messagebox.showwarning("No IDs", "Run extraction first.")
            return
        path = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text files", "*.txt")],
            initialfile="ual_message_ids.txt"
        )
        if path:
            with open(path, "w", encoding="utf-8") as f:
                f.write("\n".join(sorted(self.extracted_ids)))
            messagebox.showinfo("Saved", f"IDs saved to {path}")

    # ── PANEL: CONTENT SEARCH LOAD ────────────────────────────────────────────
    def _build_panel_cs(self):
        p = tk.Frame(self.content, bg=C["bg"])
        self.panels["cs"] = p
        inner = self._scrollable(p)
        inner.configure(padx=36, pady=28)

        tk.Label(inner, text="SECTION B — STEP 3", font=FONTS["tag"],
                 bg=C["bg"], fg=C["accent"]).pack(anchor="w")
        tk.Label(inner, text="Load Purview Items.csv",
                 font=FONTS["h1"], bg=C["bg"], fg=C["text"]).pack(anchor="w", pady=(4, 2))
        tk.Label(inner, text="Upload the Items.csv from your Content Search export ZIP (report-only, no PST content).",
                 font=FONTS["body"], bg=C["bg"], fg=C["muted"]).pack(anchor="w", pady=(0, 20))

        drop_card = card(inner)
        drop_card.pack(fill="x", pady=(0, 16))
        dc = tk.Frame(drop_card, bg=C["bg"])
        dc.pack(fill="x", padx=20, pady=20)

        self._cs_file_lbl = tk.Label(dc, text="No file loaded",
                                     font=FONTS["small"], bg=C["bg"], fg=C["muted"])
        self._cs_file_lbl.pack(anchor="w", pady=(0, 10))
        flat_btn(dc, "Browse Items.csv / XLSX", self._browse_cs, accent=True).pack(anchor="w")

        # Column mapping
        self._cs_col_card = card(inner)
        self._cs_col_card.pack(fill="x", pady=(0, 16))
        self._cs_col_inner = tk.Frame(self._cs_col_card, bg=C["bg"])
        self._cs_col_inner.pack(fill="x", padx=20, pady=16)
        tk.Label(self._cs_col_inner, text="COLUMN MAPPING — auto-detected, adjust if needed",
                 font=FONTS["tag"], bg=C["bg"], fg=C["muted"]).pack(anchor="w", pady=(0, 10))

        self._cs_cols = {}
        row_frame = tk.Frame(self._cs_col_inner, bg=C["bg"])
        row_frame.pack(fill="x")
        for i, (lbl_txt, key) in enumerate([
            ("Internet Message ID", "msgid"),
            ("Subject / Title", "subject"),
            ("Date Sent", "date"),
            ("Recipients", "recip"),
            ("Original Path", "path"),
        ]):
            cf = tk.Frame(row_frame, bg=C["bg"])
            cf.grid(row=i // 2, column=i % 2, sticky="ew", padx=(0, 16), pady=(0, 8))
            row_frame.columnconfigure(i % 2, weight=1)
            tk.Label(cf, text=lbl_txt, font=FONTS["small"],
                     bg=C["bg"], fg=C["muted"]).pack(anchor="w")
            var = tk.StringVar()
            self._cs_cols[key] = var
            cb = ttk.Combobox(cf, textvariable=var, font=FONTS["body"], state="readonly")
            cb.pack(fill="x", ipady=3)
            self._cs_col_combos = getattr(self, "_cs_col_combos_list", [])
            self._cs_col_combos.append((key, cb))
            self._cs_col_combos_list = self._cs_col_combos

        # Preview
        self._cs_preview_frame = tk.Frame(inner, bg=C["bg"])
        self._cs_preview_frame.pack(fill="x", pady=(0, 16))

        self._cs_info = tk.Label(inner, text="", font=FONTS["small"],
                                 bg=C["bg"], fg=C["green"])
        self._cs_info.pack(anchor="w", pady=(0, 8))

        self._btn_to_corr = flat_btn(inner, "Continue: Correlate & Export →",
                                     self._go_correlate)
        self._btn_to_corr.configure(state="disabled")
        self._btn_to_corr.pack(anchor="w")

    def _browse_cs(self):
        path = filedialog.askopenfilename(
            title="Select Items.csv / XLSX",
            filetypes=[("CSV/Excel", "*.csv *.xlsx *.xls"), ("All", "*.*")]
        )
        if not path:
            return
        fname = Path(path).name
        self._show_loading(fname)
        self._set_status(f"Loading {fname}...")
        threading.Thread(target=self._load_cs, args=(path,), daemon=True).start()

    def _load_cs(self, path):
        try:
            self.after(0, lambda: self._cs_file_lbl.configure(
                text="Loading… please wait", fg=C["muted"]))
            if path.lower().endswith(".csv"):
                df = pd.read_csv(path, dtype=str, low_memory=False,
                                 encoding_errors="replace")
            else:
                df = self._read_xlsx(path)
            df = df.fillna("").astype(str)
            self.cs_df = df
            self.after(0, self._cs_loaded, path, df)
        except Exception as e:
            err = str(e)
            self.after(0, lambda: (
                self._hide_loading(),
                self._cs_file_lbl.configure(text="Load failed", fg=C["red"]),
                messagebox.showerror("Load Error",
                    f"Could not load file:\n{err}\n\n"
                    "Try saving as CSV from Excel (File → Save As → CSV UTF-8).")
            ))

    def _cs_loaded(self, path, df):
        self._hide_loading()
        fname = Path(path).name
        self._cs_file_lbl.configure(
            text=f"✓  {fname}  —  {len(df):,} rows, {len(df.columns)} columns",
            fg=C["green"])
        self._cs_info.configure(text=f"Columns: {', '.join(df.columns[:8])}{'…' if len(df.columns) > 8 else ''}")

        # Populate combos
        col_names = list(df.columns)
        keywords = {
            "msgid": ["internet message", "message id", "messageid", "internetmessage"],
            "subject": ["subject", "title"],
            "date": ["date sent", "sent", "received", "date"],
            "recip": ["recipient", "email recipient", "to"],
            "path": ["path", "original path", "location"],
        }

        def find(kws):
            for c in col_names:
                if any(k in c.lower() for k in kws):
                    return c
            return col_names[0] if col_names else ""

        for key, cb in getattr(self, "_cs_col_combos_list", []):
            cb["values"] = col_names
            self._cs_cols[key].set(find(keywords.get(key, [])))

        self._btn_to_corr.configure(state="normal")
        self._mark_done("cs")
        self._set_status(f"Items.csv loaded: {len(df):,} rows")
        self._build_preview(self._cs_preview_frame, df, title="Items.csv Preview (first 5 rows)")

    def _go_correlate(self):
        self._show_panel("correlate")
        self._run_correlation()

    # ── PANEL: CORRELATE ──────────────────────────────────────────────────────
    def _build_panel_correlate(self):
        p = tk.Frame(self.content, bg=C["bg"])
        self.panels["correlate"] = p
        inner = self._scrollable(p)
        inner.configure(padx=36, pady=28)

        tk.Label(inner, text="SECTION B — STEP 4", font=FONTS["tag"],
                 bg=C["bg"], fg=C["accent"]).pack(anchor="w")
        tk.Label(inner, text="Correlate & Export",
                 font=FONTS["h1"], bg=C["bg"], fg=C["text"]).pack(anchor="w", pady=(4, 2))
        tk.Label(inner, text="Match Content Search items against UAL-extracted Internet Message IDs. Green rows = TA accessed.",
                 font=FONTS["body"], bg=C["bg"], fg=C["muted"]).pack(anchor="w", pady=(0, 20))

        self._corr_stats_frame = tk.Frame(inner, bg=C["bg"])
        self._corr_stats_frame.pack(fill="x", pady=(0, 16))

        # Filter row
        frow = tk.Frame(inner, bg=C["bg"])
        frow.pack(fill="x", pady=(0, 12))
        self._corr_search_var = tk.StringVar()
        self._corr_search_var.trace_add("write", lambda *a: self._refresh_corr_table())
        se = tk.Entry(frow, textvariable=self._corr_search_var, font=FONTS["body"],
                      bg=C["entry_bg"], fg=C["text"], relief="flat", bd=0,
                      highlightthickness=1, highlightbackground=C["border"])
        se.pack(side="left", fill="x", expand=True, ipady=5, padx=(0, 10))
        se.insert(0, "Search subject, recipient, message ID…")
        se.configure(fg=C["muted"])
        se.bind("<FocusIn>", lambda e: (se.delete(0, "end"), se.configure(fg=C["text"])) if se.get().startswith("Search") else None)

        self._corr_filter_var = tk.StringVar(value="all")
        cb = ttk.Combobox(frow, textvariable=self._corr_filter_var,
                          values=["all", "matched", "unmatched"],
                          state="readonly", width=14, font=FONTS["body"])
        cb.pack(side="left", padx=(0, 10))
        cb.bind("<<ComboboxSelected>>", lambda e: self._refresh_corr_table())

        flat_btn(frow, "⬇  Export Results (.xlsx)", self._export_xlsx, accent=True).pack(side="left")

        # Results table
        self._corr_table_frame = tk.Frame(inner, bg=C["bg"])
        self._corr_table_frame.pack(fill="both", expand=True)

        self._corr_tv = None

    def _run_correlation(self):
        if not self.extracted_ids or self.cs_df is None:
            for w in self._corr_stats_frame.winfo_children():
                w.destroy()
            tk.Label(self._corr_stats_frame,
                     text="⚠  Complete UAL extraction and load Items.csv before correlating.",
                     font=FONTS["body"], bg=C["bg"], fg=C["amber"]).pack(anchor="w")
            return

        col_map = {k: v.get() for k, v in self._cs_cols.items()}
        norm_set = {normalise_id(mid) for mid in self.extracted_ids}
        df = self.cs_df.copy()

        mid_col = col_map["msgid"]
        if mid_col not in df.columns:
            messagebox.showerror("Column Error", f"Column '{mid_col}' not found in Items.csv.")
            return

        df["_matched"] = df[mid_col].apply(lambda x: "YES" if normalise_id(str(x)) in norm_set else "NO")

        # Reorder
        keep = ["_matched"] + [c for c in [
            col_map["subject"], col_map["date"], col_map["recip"], mid_col, col_map["path"]
        ] if c in df.columns]
        other = [c for c in df.columns if c not in keep]
        self.corr_df = df[keep + other]
        self.corr_df = self.corr_df.rename(columns={"_matched": "TA Accessed"})

        matched = (self.corr_df["TA Accessed"] == "YES").sum()
        total = len(self.corr_df)

        # Stats
        for w in self._corr_stats_frame.winfo_children():
            w.destroy()
        pills = tk.Frame(self._corr_stats_frame, bg=C["bg"])
        pills.pack(fill="x")
        for val, lbl_txt, col in [
            (total, "Total Items", C["navy"]),
            (matched, "TA Accessed (Matched)", C["green"]),
            (total - matched, "Not Matched", C["red"]),
            (f"{matched/total*100:.0f}%" if total else "0%", "Match Rate", C["amber"]),
        ]:
            sp = stat_pill(pills, str(val), lbl_txt, color=col)
            sp.pack(side="left", padx=(0, 10))

        self._mark_done("correlate")
        self._set_status(f"Correlation complete: {matched:,} matched of {total:,}")
        self._refresh_corr_table()

    def _refresh_corr_table(self):
        if self.corr_df is None:
            return
        for w in self._corr_table_frame.winfo_children():
            w.destroy()

        df = self.corr_df.copy()
        q = self._corr_search_var.get().strip().lower()
        fmode = self._corr_filter_var.get()

        if fmode == "matched":
            df = df[df["TA Accessed"] == "YES"]
        elif fmode == "unmatched":
            df = df[df["TA Accessed"] == "NO"]

        if q and not q.startswith("search"):
            mask = df.apply(lambda row: row.astype(str).str.lower().str.contains(q).any(), axis=1)
            df = df[mask]

        show = df.head(500)
        tk.Label(self._corr_table_frame,
                 text=f"Showing {min(len(df), 500):,} of {len(df):,} results",
                 font=FONTS["small"], bg=C["bg"], fg=C["muted"]).pack(anchor="w", pady=(0, 6))
        self._build_table(self._corr_table_frame, show, max_cols=7, matched_col="TA Accessed")

    def _export_xlsx(self):
        if self.corr_df is None:
            messagebox.showwarning("No Data", "Run correlation first.")
            return
        path = filedialog.asksaveasfilename(
            defaultextension=".xlsx",
            filetypes=[("Excel files", "*.xlsx")],
            initialfile="CHRONOS_MailForensics_Export.xlsx"
        )
        if not path:
            return
        self._set_status("Exporting XLSX…")
        threading.Thread(target=self._write_xlsx, args=(path,), daemon=True).start()

    def _write_xlsx(self, path):
        try:
            wb = openpyxl.Workbook()

            # ── Sheet 1: All Items ──
            ws1 = wb.active
            ws1.title = "All Items"
            df_all = self.corr_df.copy()
            header_fill = PatternFill("solid", fgColor="463F3A")
            header_font = Font(color="FFFFFF", bold=True, size=10)
            match_fill = PatternFill("solid", fgColor="F7EDE9")
            border = Border(
                bottom=Side(style="thin", color="E0E0E0")
            )

            headers = list(df_all.columns)
            ws1.append(headers)
            for cell in ws1[1]:
                cell.fill = header_fill
                cell.font = header_font
                cell.alignment = Alignment(vertical="center", wrap_text=False)

            for _, row in df_all.iterrows():
                ws1.append([str(v)[:500] for v in row.values])
                if row.get("TA Accessed") == "YES":
                    last = ws1.max_row
                    for cell in ws1[last]:
                        cell.fill = match_fill

            # Auto-width
            for col in ws1.columns:
                max_len = max((len(str(c.value or "")) for c in col), default=10)
                ws1.column_dimensions[col[0].column_letter].width = min(max_len + 4, 60)
            ws1.freeze_panes = "A2"

            # ── Sheet 2: Matched Only ──
            ws2 = wb.create_sheet("TA Accessed (Matched)")
            matched = df_all[df_all["TA Accessed"] == "YES"]
            ws2.append(headers)
            for cell in ws2[1]:
                cell.fill = header_fill
                cell.font = header_font
            for _, row in matched.iterrows():
                ws2.append([str(v)[:500] for v in row.values])
                for cell in ws2[ws2.max_row]:
                    cell.fill = match_fill
            ws2.freeze_panes = "A2"

            # ── Sheet 3: UAL IDs ──
            ws3 = wb.create_sheet("UAL Message IDs")
            ws3.append(["Internet Message ID"])
            ws3["A1"].fill = header_fill
            ws3["A1"].font = header_font
            for mid in sorted(self.extracted_ids):
                ws3.append([mid])
            ws3.column_dimensions["A"].width = 80

            wb.save(path)
            self.after(0, lambda: (
                self._set_status(f"Exported: {Path(path).name}"),
                messagebox.showinfo("Export Complete",
                                    f"Results saved to:\n{path}\n\n"
                                    f"Sheets:\n  • All Items ({len(df_all):,} rows)\n"
                                    f"  • TA Accessed ({len(matched):,} rows)\n"
                                    f"  • UAL Message IDs ({len(self.extracted_ids):,})")
            ))
        except Exception as e:
            self.after(0, lambda: messagebox.showerror("Export Error", str(e)))


